{"command": "cd /testbed && python - <<'EOF'
p = "src/flask/cli.py"
s = open(p).read()
start = s.index('    name = current_app.config["SERVER_NAME"] or ""')
end = s.index('\n\n\ncli = FlaskGroup(')
new = '''    name = current_app.config["SERVER_NAME"] or ""

    def get_domain(rule: Rule) -> str:
        if rule.host:
            return rule.host

        subdomain = rule.subdomain

        if not name:
            return subdomain or "-"

        if not subdomain:
            return name

        return f"{subdomain}.{name}"

    show_domain = bool(name) or any(rule.host or rule.subdomain for rule in rules)

    if show_domain:
        rule_domains = [get_domain(rule) for rule in rules]
        headers = ("Domain", "Endpoint", "Methods", "Rule")
        rows = [
            (domain, rule.endpoint, methods, rule.rule)
            for domain, rule, methods in zip(rule_domains, rules, rule_methods)
        ]
    else:
        headers = ("Endpoint", "Methods", "Rule")
        rows = [
            (rule.endpoint, methods, rule.rule)
            for rule, methods in zip(rules, rule_methods)
        ]

    widths = [max(len(str(value)) for value in column) for column in zip(*rows)]
    widths = [max(len(header), width) for header, width in zip(headers, widths)]
    row = "  ".join(
        f"{{{index}:<{{{index}}}}}" for index in range(len(headers))
    ).format(*widths)

    click.echo(row.format(*headers).strip())
    click.echo(row.format(*("-" * width for width in widths)))

    for values in rows:
        click.echo(row.format(*values).rstrip())
'''
s = s[:start] + new + s[end:]
open(p, "w").write(s)
EOF
